import React from 'react';

export default function Navigation({ setCurrentView }) {
  return (
    <nav className="sticky top-0 z-50 bg-[#fff9f0]/95 backdrop-blur-md px-6 py-4 flex justify-between items-center border-b border-[#4a3b32]/10">
      <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('home')}>
        <span className="text-3xl text-[#8c4a2f]">🐾</span>
        <span className="font-serif font-bold text-2xl tracking-tight text-[#4a3b32]">TeddyPups</span>
      </div>
      <div className="hidden md:flex items-center gap-6 font-medium text-lg text-[#4a3b32]">
        <button onClick={() => setCurrentView('home')} className="hover:text-[#8c4a2f] transition-colors">Home</button>
        <button onClick={() => setCurrentView('puppies')} className="hover:text-[#8c4a2f] transition-colors">Puppies</button>
        <button onClick={() => setCurrentView('faq')} className="hover:text-[#8c4a2f] transition-colors">FAQ</button>
        <a href="#" className="hover:text-[#8c4a2f] transition-colors">Happy families</a>
      </div>
      <button className="bg-[#2d6a4f] hover:bg-green-900 text-white px-5 py-2 rounded-full font-medium transition-all shadow-md hidden sm:block">
        WhatsApp us
      </button>
    </nav>
  );
}
